`,s.jsxs(t.li,{children:[`
`,s.jsx(t.p,{children:"Implementing real-time multiplayer logic with WebSockets"}),`
`]}),`
`,s.jsxs(t.li,{children:[`
`,s.jsx(t.p,{children:"Designing authoritative server architecture to prevent desync"}),`
`]}),`
`,s.jsxs(t.li,{children:[`
`,s.jsx(t.p,{children:"Using nanoId for scalable, collision-resistant identifiers"}),`
`]}),`
`,s.jsxs(t.li,{children:[`
`,s.jsx(t.p,{children:"Managing deployment and infrastructure on AWS"}),`
`]}),`
`,s.jsxs(t.li,{children:[`
`,s.jsx(t.p,{children:"Handling drag-and-drop mechanics cleanly in React"}),`
`]}),`
`,s.jsxs(t.li,{children:[`
`,s.jsx(t.p,{children:"Balancing performance with development velocity"}),`
`]}),`
`]}),`
`,s.jsx(t.hr,{}),`
`,s.jsx(t.h2,{children:"What's Next"}),`
`,s.jsx(t.p,{children:"The next step is improving UI polish and responsiveness. The core game works, but the experience can feel sharper - better animations, clearer feedback, and improved mobile responsiveness would elevate the gameplay significantly."}),`
`,s.jsx(t.p,{children:"I also want to improve matchmaking reliability and scalability. Moving from in-memory queues to a more persistent or distributed approach would make the system more production-ready. Performance tuning beyond the current 20 FPS update cycle is another area I’d like to explore once the infrastructure becomes more robust."})]})}function NE(i={}){const{wrapper:t}=i.components||{};return t?s.jsx(t,{...i,children:s.jsx(Cy,{...i})}):Cy(i)}function My(i){const t={h2:"h2",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...i.components};return s.jsxs(s.Fragment,{children:[s.jsx(t.hr,{}),`
`,s.jsx(t.h2,{children:"Introduction"}),`
`,s.jsx(t.p,{children:"This project started as a simple experiment to learn web scraping. I just wanted to pull some movie data and understand how scraping pipelines worked end-to-end."}),`
`,s.jsx(t.p,{children:"But as I was building it, I realized the data itself was actually interesting. Instead of stopping at a CSV file, I decided to turn it into something visual — a dashboard that shows where the top 100 most popular movies on IMDb were filmed. I’ve always thought 3D globe visualizations on the web looked cool, so this felt like the perfect excuse to finally use one."}),`
`,s.jsx(t.p,{children:"The result is a full-stack application that scrapes IMDb every 6 hours via an automated ETL pipeline and visualizes filming locations on an interactive globe."}),`
`,s.jsx(t.hr,{}),`
