`,s.jsxs(t.ul,{children:[`
`,s.jsx(t.li,{children:"Order insertion"}),`
`,s.jsx(t.li,{children:"Order cancellation"}),`
`,s.jsx(t.li,{children:"Matching behavior"}),`
`,s.jsx(t.li,{children:"Data structure integrity"}),`
`,s.jsx(t.li,{children:"Consistent behavior across implementations"}),`
`]}),`
`,s.jsx(t.p,{children:"While developing the project, I gained a much greater appreciation for testing. Small bugs in matching logic or order tracking can produce incorrect market states that are difficult to detect without automated validation."}),`
`,s.jsx(t.hr,{}),`
